import java.io.File;
import java.nio.file.Path;
import java.util.Objects;

public class ImportingUtilities {

    // other methods

    static public File allocateFile(File dir, String name) {
        // Validate inputs
        Objects.requireNonNull(dir, "Target directory cannot be null");
        Objects.requireNonNull(name, "File name cannot be null");

        // Strip query parameters if present
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve the requested file against the base directory and normalize the path
        Path basePath = dir.toPath().toAbsolutePath().normalize();
        Path resolvedPath = basePath.resolve(name).normalize();

        // Ensure the resolved path stays within the base directory
        if (!resolvedPath.startsWith(basePath)) {
            throw new IllegalArgumentException(
                "Attempted to create a file outside the target directory: " + name);
        }

        // Prepare the initial File instance
        File file = resolvedPath.toFile();

        // Split the name into prefix and suffix for duplicate handling
        int dot = name.indexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);

        // Append numeric suffixes until a non‑existing file name is found
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Create parent directories if they do not exist
        file.getParentFile().mkdirs();

        return file;
    }

    // other methods
}
