import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.security.SecureRandom;
import org.springframework.beans.factory.FactoryBean;
import org.springframework.core.io.Resource;
import org.springframework.util.FileCopyUtils;

public class SecureRandomFactoryBean implements FactoryBean<SecureRandom> {

    private String algorithm = "SHA1PRNG";
    private Resource seed;

    // other methods omitted for brevity

    @Override
    public SecureRandom getObject() throws Exception {
        // Obtain a SecureRandom instance using the specified algorithm.
        // The default constructor of SecureRandom already performs
        // high‑entropy seeding from the operating system, so no
        // explicit seeding is required.
        SecureRandom rnd = SecureRandom.getInstance(algorithm);

        // If a seed resource is supplied, do NOT use it to seed the
        // SecureRandom instance. Reading the resource is allowed only
        // to consume it (e.g., for logging or validation purposes),
        // but the data must not influence the randomness.
        if (seed != null) {
            try (InputStream is = seed.getInputStream()) {
                // Consume the stream without affecting the RNG.
                // The content is discarded; no seeding occurs.
                FileCopyUtils.copy(is, new ByteArrayOutputStream());
            } catch (IOException e) {
                // Propagate I/O errors – they indicate a problem with
                // accessing the seed resource, which should not be silently ignored.
                throw e;
            }
        }

        // No further seeding is performed; the SecureRandom instance
        // is fully initialized by its internal entropy pool.
        return rnd;
    }

    // other methods omitted for brevity
}
