public class SAMLSSOResponseValidator {

    private static final Logger LOG = LogUtils.getL7dLogger(SAMLSSOResponseValidator.class);

    private String assertionConsumerURL;
    private boolean enforceAssertionsSigned = true;

    /* Allowed signature algorithms – only those that provide adequate security. */
    private static final Set<String> ALLOWED_SIGNATURE_METHODS =
            new HashSet<>(Arrays.asList(
                    "http://www.w3.org/2001/04/xmldsig-more#rsa-sha256",
                    "http://www.w3.org/2001/04/xmldsig-more#rsa-sha512",
                    "http://www.w3.org/2001/04/xmldsig-more#ecdsa-sha256",
                    "http://www.w3.org/2001/04/xmldsig-more#ecdsa-sha384",
                    "http://www.w3.org/2001/04/xmldsig-more#ecdsa-sha512"));

    /* Exclusive canonicalisation is required to avoid canonicalisation attacks. */
    private static final String EXCLUSIVE_C14N_ALGORITHM =
            "http://www.w3.org/2001/10/xml-exc-c14n#";

