     * Validate a SAML 2 Protocol Response.
     *
     * @param samlResponse the parsed SAML response
     * @param postBinding  true if the response was received via HTTP‑POST
     * @return a populated {@link SSOValidatorResponse}
     * @throws WSSecurityException if the response fails validation
     */
    public SSOValidatorResponse validateSamlResponse(Response samlResponse, boolean postBinding)
            throws WSSecurityException {

        /* Basic checks on the response itself. */
        validateIssuer(samlResponse.getIssuer());

        if (samlResponse.getAssertions() == null || samlResponse.getAssertions().isEmpty()) {
            LOG.fine("The Response must contain at least one Assertion");
            throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
        }

        if (samlResponse.getID() == null || samlResponse.getID().trim().isEmpty()) {
            LOG.fine("The Response must have a non‑empty ID");
            throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
        }

        /* Verify that the response signature covers the entire response. */
        if (samlResponse.isSigned()) {
            Signature respSig = samlResponse.getSignature();
            if (respSig == null) {
                LOG.fine("Response claims to be signed but no Signature element found");
                throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
            }
            validateSignatureReference(respSig, samlResponse.getID());
            validateSignatureAlgorithm(respSig);
            validateCanonicalizationMethod(respSig);
        }

        /* Destination must match the assertion consumer URL. */
        String destination = samlResponse.getDestination();
        if (samlResponse.isSigned() && (destination == null || !destination.equals(assertionConsumerURL))) {
            LOG.fine("The Response must contain a destination that matches the assertion consumer URL");
            throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
        }

        boolean foundValidSubject = false;
        Date sessionNotOnOrAfter = null;
        Set<String> seenAssertionIds = new HashSet<>();

        for (Assertion assertion : samlResponse.getAssertions()) {
            /* Each assertion must have a unique ID. */
            String assertionId = assertion.getID();
            if (assertionId == null || assertionId.trim().isEmpty()) {
                LOG.fine("Assertion must have a non‑empty ID");
                throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
            }
            if (!seenAssertionIds.add(assertionId)) {
