     *
     * @param request     current HTTP request
     * @param response    current HTTP response
     * @param resourceUrl the URL of the target resource
     * @throws ServletException if thrown by the RequestDispatcher
     * @throws IOException       if thrown by the RequestDispatcher
     */
    private void doInclude(HttpServletRequest request, HttpServletResponse response,
                           String resourceUrl) throws ServletException, IOException {
        if (resourceUrl == null || resourceUrl.trim().isEmpty()) {
            return; // nothing to include
        }

        if (this.contentType != null) {
            response.setContentType(this.contentType);
        }

        String[] resourceUrls = StringUtils.tokenizeToStringArray(resourceUrl, RESOURCE_URL_DELIMITERS);
        for (String url : resourceUrls) {
            url = url.trim();
            if (url.isEmpty()) {
                continue;
            }

            /* ---------- Input validation & sanitisation ---------- */
            // Reject obvious traversal attempts
            if (url.contains("..") || url.startsWith("/") || url.contains("\\")) {
                throw new ServletException("Potential path traversal detected: " + url);
            }

            // Resolve the path and normalise it
            Path path = Paths.get(url).normalize();

            // Reject absolute paths or paths that still contain '..' after normalisation
            if (path.isAbsolute() || path.startsWith("..")) {
                throw new ServletException("Absolute or relative traversal path not allowed: " + url);
            }

            // Convert to a consistent forward‑slash representation
            String safeUrl = path.toString().replace(File.separatorChar, '/');

            /* ---------- Allowed resources check ---------- */
            if (this.allowedResources != null &&
                !this.pathMatcher.match(this.allowedResources, safeUrl)) {
                throw new ServletException(
                        "Resource [" + safeUrl + "] does not match allowed pattern ["
                                + this.allowedResources + "]");
            }

            if (logger.isDebugEnabled()) {
                logger.debug("Including resource [{}]", safeUrl);
            }

            RequestDispatcher rd = request.getRequestDispatcher(safeUrl);
            rd.include(request, response);
        }
    }

    // other methods
}
