@Override
public ByteBuffer encode(final String name) {
    final CharsetEncoder enc = newEncoder();
    // Use replace actions to avoid infinite loops on malformed/unmappable input
    enc.onMalformedInput(java.nio.charset.CodingErrorAction.REPLACE);
    enc.onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPLACE);

    final CharBuffer cb = CharBuffer.wrap(name);
    ByteBuffer out = ByteBuffer.allocate(estimateInitialBufferSize(enc, cb.remaining()));

    // Track how many times we have attempted to encode the same character
    int retryLimit = 10;
    int retryCount = 0;

    while (cb.remaining() > 0) {
        final CoderResult res = enc.encode(cb, out, false);

        if (res.isOverflow()) {
            // Grow the output buffer to accommodate more bytes
            int increment = estimateIncrementalEncodingSize(enc, cb.remaining());
            out = ZipEncodingHelper.growBufferBy(out, increment);
            continue; // retry encoding after growing
        }

        if (res.isError()) {
            // If we cannot make progress, consume one character manually
            if (retryCount >= retryLimit) {
                throw new IllegalArgumentException(
                    "Unable to encode character after " + retryLimit + " retries");
            }
            // Consume the problematic character
            char problematic = cb.get();
            // Encode the replacement character(s) directly
            CharBuffer repl = CharBuffer.wrap(new char[] { enc.replacement()[0] });
            // Ensure the output buffer has enough space
            if (out.remaining() < repl.remaining()) {
                int inc = estimateIncrementalEncodingSize(enc, repl.remaining());
                out = ZipEncodingHelper.growBufferBy(out, inc);
            }
            enc.encode(repl, out, false);
            retryCount++;
            continue;
        }

        // Successful encoding; reset retry counter
        retryCount = 0;
    }

    // Flush any remaining state
    enc.encode(cb, out, true);
    enc.flush(out);

    out.limit(out.position());
    out.rewind();
    return out;
