private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory, Object principal, Object credentials) throws NamingException {
    if (!(ldapContextFactory instanceof JndiLdapContextFactory)) {
        throw new IllegalArgumentException("Unsupported LdapContextFactory type");
    }
    JndiLdapContextFactory jndiFactory = (JndiLdapContextFactory) ldapContextFactory;
    Hashtable<String, Object> env = new Hashtable<>();
    env.put(Context.INITIAL_CONTEXT_FACTORY, jndiFactory.getContextFactoryClassName());
    env.put(Context.PROVIDER_URL, jndiFactory.getUrl());
    // Set authentication mechanism early
    env.put(Context.SECURITY_AUTHENTICATION, jndiFactory.getAuthenticationMechanism());
    // Set principal/credentials
    if (principal == null || credentials == null) {
        throw new IllegalArgumentException("Principal and credentials must not be null");
    }
    env.put(Context.SECURITY_PRINCIPAL, principal);
    env.put(Context.SECURITY_CREDENTIALS, credentials);
    LdapContext ctx = null;
    try {
        ctx = new InitialLdapContext(env, null);
        // Negotiate STARTTLS
        StartTlsRequest startTlsRequest = new StartTlsRequest();
        StartTlsResponse tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
        tls.negotiate();
        // Force authentication by performing a simple lookup
        ctx.lookup("");
        return ctx;
    } catch (AuthenticationException ae) {
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm("Authentication failed for principal '%s' against '%s': %s",
                principal, server(jndiFactory), ae.getMessage()), ae);
        throw new NamingException("Authentication failed: " + ae.getMessage());
    } catch (IOException | NamingException e) {
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm("Failed to establish secure LDAP connection with '%s': %s",
                server(jndiFactory), e.getMessage()), e);
        throw e;
    } catch (Throwable t) {
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm("Unexpected failure to establish secure LDAP connection with '%s': %s",
                server(jndiFactory), t.getMessage()), t);
        throw t;
    }
}

