import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.apache.commons.compress.archivers.ArchiveEntry;

public class Expander {

    // other methods

    /**
     * Safely expands archive entries into the specified target directory.
     *
     * <p>This method performs rigorous path validation to prevent path‑traversal attacks.
     * It normalises and resolves all entry paths against the canonical target directory,
     * rejects absolute paths, and ensures that even symlinked destinations cannot escape
     * the intended extraction root.</p>
     *
     * @param supplier      provides the next readable archive entry
     * @param writer        writes entry data to an {@link OutputStream}
     * @param targetDirectory the root directory where entries should be extracted
     * @throws IOException if an I/O error occurs or a path traversal attempt is detected
     */
    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Canonical path of the extraction root – used for all subsequent checks
        Path canonicalTargetDir = targetDirectory.getCanonicalFile().toPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Reject absolute paths (leading '/' or '\')
            if (entryName.startsWith("/") || entryName.startsWith("\\")) {
                throw new IOException("Archive entry has absolute path: " + entryName);
            }

            // Resolve the entry against the target directory and normalise the path
            Path resolvedPath = canonicalTargetDir.resolve(entryName).normalize();

            // Ensure the resolved path is still within the target directory
            if (!resolvedPath.startsWith(canonicalTargetDir)) {
                throw new IOException("Archive entry would escape target directory: " + entryName);
            }

            // Convert to File for further operations
            File f = resolvedPath.toFile();

            // Resolve symlinks and verify again that the canonical destination stays inside
            File canonicalF = f.getCanonicalFile();
            Path canonicalResolvedPath = canonicalF.toPath();
            if (!canonicalResolvedPath.startsWith(canonicalTargetDir)) {
                throw new IOException("Archive entry resolves to a location outside the target directory: " + entryName);
            }

            if (nextEntry.isDirectory()) {
                if (!canonicalF.isDirectory() && !canonicalF.mkdirs()) {
                    throw new IOException("Failed to create directory " + canonicalF);
                }
            } else {
                File parent = canonicalF.getParentFile();
                if (!parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("Failed to create directory " + parent);
                }

                // Write the file contents atomically
                try (OutputStream out = Files.newOutputStream(canonicalResolvedPath,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
