     * @throws IOException if an I/O error occurs while reading the request body
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // 1. Identify the authenticated user
        String authenticatedUserId = getAuthenticatedUserId(request);
        if (authenticatedUserId == null) {
            // No authenticated principal – deny access
            return false;
        }

        // 2. Parse the request body safely
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest;
        try {
            scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);
        } catch (Exception e) {
            // Malformed JSON – deny access
            return false;
        }

        // 3. Extract the target user ID from the request path
        String id = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // 4. Ensure the authenticated user is updating their own record
        if (!authenticatedUserId.equals(id)) {
            return false;
        }

        // 5. Retrieve the user from the database
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // User does not exist – allow creation (handled elsewhere)
            return true;
        }

        // 6. Perform field‑level consistency checks
        if (!scimUserFromDb.getPrimaryEmail().equals(scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!scimUserFromDb.getUserName().equals(scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!scimUserFromDb.getOrigin().equals(scimUserFromRequest.getOrigin())) {
            return false;
        }

        return true;
    }

    /**
     * Retrieves the authenticated user ID from the request.
     *
     * <p>This implementation assumes that the {@link Principal#getName()}
     * method returns the unique user identifier used by the SCIM service.
     * Adjust this method if a different mechanism is used for authentication.</p>
     *
     * @param request the HTTP request
     * @return the authenticated user ID, or {@code null} if none is present
     */
    private String getAuthenticatedUserId(HttpServletRequest request) {
        Principal principal = request.getUserPrincipal();
        return (principal != null) ? principal.getName() : null;
    }

